Let $r\in\mathbb{N}$, $T>0$, let $\mathcal{G}: C^r(\mathbb{T}^d)\to C^r(\mathbb{T}^d)$ be an operator that maps a function $u_0$ to the solution $u(\cdot, T)$ of the PDE (2.1) with initial condition $u_0$, let Assumption 3.6 be satisfied {\color{black}and let $p^*\in\{2,\infty\}\setminus\{p\}$}. Then there exists a constant $C>0$ such that for every $\varepsilon>0$, $N\in\mathbb{N}$ there is an FNO $\mathcal{G}_\theta: L^2_N(\mathbb{T}^d)\to L^2_N(\mathbb{T}^d)$ of depth $\mathcal{O}(\mathrm{depth}(\mathcal{U}^\varepsilon))$ and width $\mathcal{O}(N^d\mathrm{width}(\mathcal{U}^\varepsilon))$ with accuracy, 
\begin{equation}
    \norm{\mathcal{G}-\mathcal{G}_\theta}_{L^2}
\leq C(\varepsilon + C^\varepsilon_{\mathrm{stab}}BN^{-r+d/p^*}+ C_{\varepsilon,r}^{CB}N^{-r}).
\end{equation}

Let $s,r\in\mathbb{N}$, let $u\in C^{(s,r)}([0,T]\times D)$ be the solution of the PDE (2.1) and let Assumption 3.1 be satisfied. There exists a constant $C(s,r)>0$ such that for every $M\in\mathbb{N}$ and $\varepsilon, h>0$ there exists a tanh neural network $u_\theta:[0,T]\times D\to \mathbb{R}$ for which it holds that,
\begin{equation}

    \norm{u_\theta-u}_{L^q([0,T]\times D)} \leq C(\norm{u}_{C^{(s,0)}}M^{-s}+\varepsilon). 
\end{equation}
and if additionally Assumption 3.3 and Assumption 3.4 hold then,
\begin{equation}
\begin{split}
     &\norm{\mathcal{L}(u_\theta)}_{L^2([0,T]\times D)} + \norm{u_\theta-u}_{L^2(\partial([0,T]\times D))} \\
     &\qquad \leq C\cdot \mathrm{poly}(d)\cdot \ln^k(M)(\norm{u}_{C^{(s,\ell)}}M^{k-s}+M^{2k}(\varepsilon h^{-\ell}+C^B_{\varepsilon,\ell}h^{r-\ell})). 
\end{split}
\end{equation}
Moreover, $\mathrm{depth}(u_\theta)\leq C\cdot\mathrm{depth}(\mathcal{U}^\varepsilon)$ and $\mathrm{width}(u_\theta) \leq CM\cdot \mathrm{width}(\mathcal{U}^\varepsilon)$.

Consider an operator $\mathcal{G}:\mathcal{X}\to C^r(D)$, $r\in\mathbb{N}$, that satisfies Assumption 3.3 and Assumption 3.4 with $\ell\in N$. Let $\lambda^*\in (0,\infty]$, let $\lambda, C(\lambda)>0$ with $\lambda\leq\lambda^*$ and let $\sigma:\mathbb{N}\to\mathbb{R}$ be a function such that for all $p\in \mathbb{N}$ there is a DeepONet/FNO $\mathcal{G}_\theta$ such that

\begin{equation}
    \norm{\mathcal{G}(v)-\mathcal{G}_\theta(v)}_{L^2(D)}\leq Cp^{-\lambda}\qquad \text{and} \qquad \abs{\mathcal{G}_\theta(v)}_{C^r(D)}\leq Cp^{\sigma(r)}\quad \forall r\in\mathbb{N}, v\in\mathcal{X}. 
\end{equation}
Then for all $\beta\in\mathbb{R}$ with $0<\beta\leq \frac{(r-\ell)\lambda^*-\ell\sigma(r)}{r}$ there exists a constant $C^*>0$ such that for all $v\in \mathcal{X}$ and $p\in\mathbb{N}$

it holds that
\begin{equation}
    \norm{\mathcal{L}(\mathcal{G}_\theta(v))}_{L^2(D)} \leq C^*p^{-\beta}.
\end{equation}

Consider an operator $\mathcal{G}:\mathcal{X}\to C^r(D)$, $r\in\mathbb{N}$, that satisfies Assumption 3.3 and Assumption 3.4 with $\ell\in N$. Let $\lambda^*\in (0,\infty]$, let $\lambda, C(\lambda)>0$ with $\lambda\leq\lambda^*$ and let $\sigma:\mathbb{N}\to\mathbb{R}$ be a function such that for all $p\in \mathbb{N}$ there is a DeepONet/FNO $\mathcal{G}_\theta$ such that

\begin{equation}
    \norm{\mathcal{G}(v)-\mathcal{G}_\theta(v)}_{L^2(D)}\leq Cp^{-\lambda}\qquad \text{and} \qquad \abs{\mathcal{G}_\theta(v)}_{C^r(D)}\leq Cp^{\sigma(r)}\quad \forall r\in\mathbb{N}, v\in\mathcal{X}. 
\end{equation}
Then for all $\beta\in\mathbb{R}$ with $0<\beta\leq \frac{(r-\ell)\lambda^*-\ell\sigma(r)}{r}$ there exists a constant $C^*>0$ such that for all $v\in \mathcal{X}$ and $p\in\mathbb{N}$

it holds that
\begin{equation}
    \norm{\mathcal{L}(\mathcal{G}_\theta(v))}_{L^2(D)} \leq C^*p^{-\beta}.
\end{equation}

Let $s,r\in\mathbb{N}$, $T>0$, let $\mathcal{G}: C^r(\mathbb{T}^d)\to C^{(s,r)}([0,T]\times \mathbb{T}^d)$ be an operator that maps a function $u_0$ to the solution $u$ of the PDE (2.1) with initial condition $u_0$, let Assumption 3.1 and Assumption 3.6 be satisfied {\color{black}and let $p^*\in\{2,\infty\}\setminus\{p\}$}. There exists a constant $C>0$ such that for every $Z,N,M\in\mathbb{N}$, $\varepsilon, \rho>0$ there is an DeepONet $\mathcal{G}_\theta: C^r(\mathbb{T}^d)\to L^2([0,T]\times\mathbb{T}^d)$ with $Z^d$ sensors with accuracy, 
\begin{equation}
    \norm{\mathcal{G}(v)-\mathcal{G}_\theta(v)}_{L^2([0,T]\times\mathbb{T}^d)} \leq CM^{\rho}(\norm{u}_{C^{(s,0)}}M^{-s}+M^{s-1}(\varepsilon+C^\varepsilon_{\mathrm{stab}}Z^{-r+d/p^*}+C^{CB}_{\varepsilon,r}N^{-r}))
\end{equation}
and if additionally Assumption 3.3 and Assumption 3.4 hold then,
\begin{equation}
    \norm{\mathcal{L}(\mathcal{G}_\theta(v))}_{L^2([0,T]\times\mathbb{T}^d)} \leq CM^{k+\rho}(\norm{u}_{C^{(s,\ell)}}M^{-s}+M^{s-1}N^\ell(\varepsilon+C^\varepsilon_{\mathrm{stab}}Z^{-r+d/p^*}+C^{CB}_{\varepsilon,r}N^{-r})), 
\end{equation}
for all $v$. Moreover, it holds that, $\mathrm{depth}({\bm{\beta}})=\mathrm{depth}(\mathcal{U}^\varepsilon)$, $\mathrm{width}({\bm{\beta}}) = \mathcal{O}(M(Z^d+N^d\mathrm{width}(\mathcal{U}^\varepsilon)))$, 
$\mathrm{depth}({\bm{\tau}}) = 3$ and $\mathrm{width}({\bm{\tau}}) = \mathcal{O}(MN^d(N+\ln(N)))$.
